create table if not exists public.election_governance_assurance_attestations(id uuid primary key default gen_random_uuid(),award_space_id uuid not null references public.award_spaces(id) on delete cascade,report_id uuid not null references public.election_governance_assurance_reports(id) on delete cascade,attestation_type text not null check(attestation_type in('management','oversight')),statement text not null,status text not null default 'attested' check(status in('attested','withdrawn')),attested_by uuid not null references public.admins(id),attested_at timestamptz not null default now(),withdrawn_at timestamptz,withdrawal_reason text,unique(report_id,attestation_type,attested_by));
create index if not exists assurance_attestations_idx on public.election_governance_assurance_attestations(award_space_id,report_id,attested_at desc);
alter table public.election_governance_assurance_attestations enable row level security;
